select is(pg_temp.count_call('post_stock_adjustment',pg_temp.count_action('post'),3,'count-post'),(select r from responses where name='count-post'),'count posting replay creates no second adjustment');
select is((select sum(base_debit-base_credit) from finance.journal_lines where tenant_id=pg_temp.fid('t')),0::numeric,'count journal balances exactly');
select is((select base_debit from finance.journal_lines where tenant_id=pg_temp.fid('t') and account_id=pg_temp.fid('variance-account')),20.024691::numeric,'count posts exact variance expense');
select throws_ok($$update inventory.stock_counts set reason='changed' where id=pg_temp.fid('count')$$,'55000',null,'posted count is immutable');
set constraints all immediate;
select throws_ok($$select pg_temp.count_call('upsert_stock_count',pg_temp.count_payload('bad-correction')||jsonb_build_object('corrects_count_id',pg_temp.fid('missing')))$$,'22023','COUNT_CORRECTION_SOURCE_INVALID','correction source must be a posted scoped count');
select pg_temp.count_call('upsert_stock_count',pg_temp.count_payload('correction','6')||jsonb_build_object('corrects_count_id',pg_temp.fid('count')));
select is((select corrects_count_id from inventory.stock_counts where id=pg_temp.fid('correction')),pg_temp.fid('count'),'correction retains original posted count link');
select pg_temp.count_call('transition_stock_count',pg_temp.count_action('submit','correction'),1);
select pg_temp.actor('approver');
select pg_temp.count_call('transition_stock_count',jsonb_build_object('document_id',pg_temp.fid('correction'),'decision','approved'),2);
select pg_temp.actor('actor');
update inventory.stock_valuations set carrying_value=carrying_value+1 where stock_balance_id=pg_temp.fid('plain.bal');
select throws_ok($$select pg_temp.count_call('post_stock_adjustment',pg_temp.count_action('post','correction'),3)$$,'55000','COUNT_REAPPROVAL_REQUIRED','valuation drift cannot bypass approved amount');
select is((select on_hand_quantity from inventory.stock_balances where id=pg_temp.fid('plain.bal')),7::numeric,'valuation drift failure preserves stock');
update inventory.stock_valuations set carrying_value=carrying_value-1 where stock_balance_id=pg_temp.fid('plain.bal');
update inventory.stock_balances set allocated_quantity=7 where id=pg_temp.fid('plain.bal');
select throws_ok($$select pg_temp.count_call('post_stock_adjustment',pg_temp.count_action('post','correction'),3)$$,'55000','COUNT_RESERVED_STOCK_UNAVAILABLE','approved count still cannot consume new reservations');
update inventory.stock_balances set allocated_quantity=0 where id=pg_temp.fid('plain.bal');
select pg_temp.count_call('upsert_stock_count',pg_temp.count_payload('capture','0')||'{"capture_only":true}');
select is((select lines->0->>'counted_quantity' from inventory.stock_counts where id=pg_temp.fid('capture')),'7.000000','capture mode initializes physical count to locked baseline');
select is((select lines->0->>'variance_quantity' from inventory.stock_counts where id=pg_temp.fid('capture')),'0.000000','capturing cutoff creates no artificial shortage');
select throws_ok($$select pg_temp.count_call('upsert_stock_count',pg_temp.count_payload('capture','6'),99)$$,'40001','VERSION_CONFLICT','stale count edit rejected');
select pg_temp.count_call('upsert_stock_count',jsonb_set(pg_temp.count_payload('capture','6'),'{lines,0,baseline_quantity}','"999"'),1);
select is((select lines->0->>'baseline_quantity' from inventory.stock_counts where id=pg_temp.fid('capture')),'7.000000','caller cannot replace captured baseline');
select throws_ok($$select pg_temp.count_call('upsert_stock_count',jsonb_set(pg_temp.count_payload('capture','6'),'{lines,0,line_id}',to_jsonb(pg_temp.fid('replacement'))),2)$$,'22023','COUNT_BASELINE_IMMUTABLE','captured line identity cannot be replaced');
select is(jsonb_array_length(api.stock_count_options(pg_temp.fid('t'),pg_temp.fid('e'),pg_temp.fid('b'),'accounts')->'items'),1,'count picker only exposes eligible expense accounts');
select pg_temp.actor('outsider');
