select is((select on_hand_quantity from inventory.stock_balances where id=pg_temp.fid('serial.bal')),7::numeric,'serial restoration conserves exact stock');
-- Identity edits cannot replace the server's snapshot or resurrect moved stock.
select pg_temp.count_call('upsert_stock_count',pg_temp.tracked_payload('serial-guard','serial'));
select throws_ok($$select pg_temp.count_call('upsert_stock_count',jsonb_set(pg_temp.saved_count('serial-guard'),'{lines,0,identities,0,id}',to_jsonb(pg_temp.fid('foreign-serial'))),1)$$,'22023','COUNT_IDENTITIES_IMMUTABLE','unknown serial cannot replace a captured identity');
select throws_ok($$select pg_temp.count_call('upsert_stock_count',jsonb_set(pg_temp.saved_count('serial-guard'),'{lines,0,identities,0,counted_quantity}','"0.5"'),1)$$,'22023','COUNT_SERIAL_PRESENCE_REQUIRED','serial counts reject fractional presence');
select pg_temp.count_call('upsert_stock_count',jsonb_set(pg_temp.saved_count('serial-guard'),'{lines,0,identities,0,counted_quantity}','"0"'),1);
