insert into inventory.lots(id,tenant_id,legal_entity_id,product_id,code,created_by,updated_by)
values(pg_temp.fid('lot.second'),pg_temp.fid('t'),pg_temp.fid('e'),pg_temp.fid('lot'),'LOT-2',pg_temp.fid('actor'),pg_temp.fid('actor'));
insert into inventory.lot_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,lot_id,on_hand_quantity,created_by,updated_by)
values(pg_temp.fid('t'),pg_temp.fid('e'),pg_temp.fid('b'),pg_temp.fid('w'),pg_temp.fid('lot'),pg_temp.fid('lot.second'),0,pg_temp.fid('actor'),pg_temp.fid('actor'));
select pg_temp.count_call('upsert_stock_count',pg_temp.tracked_payload('lot-redistribute','lot'));
select pg_temp.count_call('upsert_stock_count',jsonb_set(pg_temp.saved_count('lot-redistribute'),'{lines,0,identities}',
 (select jsonb_agg(z||jsonb_build_object('counted_quantity',case when z->>'id'=pg_temp.fid('lot.id')::text then '1' else '2' end)) from jsonb_array_elements(pg_temp.saved_count('lot-redistribute')#>'{lines,0,identities}')z)),1);
select ok((select grand_total>0 and (lines->0->>'variance_quantity')::numeric=0 from inventory.stock_counts where id=pg_temp.fid('lot-redistribute')),'offsetting lot deltas retain a nonzero approval basis');
select pg_temp.approve_count('lot-redistribute');
select pg_temp.count_call('post_stock_adjustment',pg_temp.count_action('post','lot-redistribute'),pg_temp.count_version('lot-redistribute'));
select is((select on_hand_quantity from inventory.lot_balances where warehouse_id=pg_temp.fid('w') and lot_id=pg_temp.fid('lot.second')),2::numeric,'net-zero product count still posts identity redistribution');
select is((select sum(base_value) from inventory.stock_movement_lines ml join inventory.stock_movements m on m.id=ml.stock_movement_id where m.source_id=pg_temp.fid('lot-redistribute')),0::numeric,'identity cumulative rounding conserves exact product value');
set constraints all immediate;
select ok(not (api.stock_counts_page(pg_temp.fid('t'),pg_temp.fid('e'),pg_temp.fid('b'))->'items'->0 ? 'lines'),'register pages omit identity detail');
select ok(api.stock_count_detail(pg_temp.fid('t'),pg_temp.fid('e'),pg_temp.fid('b'),pg_temp.fid('serial-count')) ? 'lines','scoped detail retains count identities');
select throws_ok($$select api.stock_count_detail(pg_temp.fid('t'),pg_temp.fid('e'),pg_temp.fid('b2'),pg_temp.fid('serial-count'))$$,'P0002','DOCUMENT_NOT_FOUND','detail cannot cross branch boundary');
-- Limit boundary: no prefix of a large identity set can silently become a cutoff.
insert into inventory.serials(id,tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,code,created_by,updated_by)
select pg_temp.fid('limit.serial.'||x),pg_temp.fid('t'),pg_temp.fid('e'),pg_temp.fid('b'),pg_temp.fid('w'),pg_temp.fid('serial'),'LIMIT-'||x,pg_temp.fid('actor'),pg_temp.fid('actor')
from generate_series(1,500-(select count(*)::integer from inventory.serials where tenant_id=pg_temp.fid('t') and warehouse_id=pg_temp.fid('w') and product_id=pg_temp.fid('serial') and status in('available','quarantine','count_missing')))x;
select is(jsonb_array_length(inventory.count_identities(pg_temp.fid('t'),pg_temp.fid('w'),pg_temp.fid('serial'),'serial',null,null)),500,'500 captured identities are accepted in full');
insert into inventory.serials(id,tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,code,created_by,updated_by)
values(pg_temp.fid('limit.serial.excess'),pg_temp.fid('t'),pg_temp.fid('e'),pg_temp.fid('b'),pg_temp.fid('w'),pg_temp.fid('serial'),'LIMIT-EXCESS',pg_temp.fid('actor'),pg_temp.fid('actor'));
select throws_ok($$select pg_temp.count_call('upsert_stock_count',pg_temp.tracked_payload('too-many-identities','serial'))$$,'22023','COUNT_IDENTITY_LIMIT','501 identities reject capture without truncation');
select is((select count(*) from inventory.stock_counts where id=pg_temp.fid('too-many-identities')),0::bigint,'oversized identity rejection leaves no partial count');

select pg_temp.actor('actor','aal1');
select throws_ok($$select pg_temp.call(pg_temp.payload('no-mfa'))$$,'42501',null,'MFA required');
select pg_temp.actor('outsider');
select throws_ok($$select pg_temp.call(pg_temp.payload('outside'))$$,'42501',null,'outsider denied');
set local role authenticated;
select throws_ok($$select * from inventory.transfer_lines$$,'42501',null,'raw value rows denied');
select throws_ok($$insert into inventory.transfers(id) values(gen_random_uuid())$$,'42501',null,'direct writes denied');
reset role;
select * from finish();
select jsonb_agg(message) results from transfer_results;
rollback;
